--
-- Table structure for table `Properties`
--

DROP TABLE IF EXISTS `Properties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Properties` (
  `id` int NOT NULL AUTO_INCREMENT,
  `brokerId` int NOT NULL,
  `coverPhoto` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shortDescription` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `longDescription` text COLLATE utf8mb4_general_ci,
  `priceRange` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `budgetType` enum('Budgeted','Mid-Budget','Premium-Budget') COLLATE utf8mb4_general_ci NOT NULL,
  `city` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `suburb` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `googleMapLink` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `propertyType` enum('Flat','Apartment','Independent House','Villa','Plots') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('Launching Soon','Ready to Move In','Under Construction') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bathrooms` int DEFAULT NULL,
  `furnishedStatus` enum('Fully Furnished','Semi-Furnished','Unfurnished') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `parkingAvailable` tinyint(1) DEFAULT NULL,
  `launchDate` datetime DEFAULT NULL,
  `completionDate` datetime DEFAULT NULL,
  `floorNumber` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `numberOfTowers` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `carpetArea` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `totalArea` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `facing` enum('East Facing','West Facing','North Facing','South Facing') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `approvalStatus` enum('pending','approved','rejected') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `bedrooms` int DEFAULT NULL,
  `district` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `state` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pincode` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` text COLLATE utf8mb4_general_ci,
  `road` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `country` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `continent` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `timezone` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isoCode` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `seoTitle` varchar(60) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SEO optimized title',
  `metaDescription` varchar(160) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Meta description',
  `metaKeywords` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Comma-separated keywords',
  `ogTitle` varchar(60) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Open Graph title',
  `ogType` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'website' COMMENT 'Open Graph type',
  `ogDescription` varchar(160) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Open Graph description',
  `twitterCard` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'summary_large_image' COMMENT 'Twitter card type',
  `canonicalUrl` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Canonical URL',
  `focusKeyword` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Focus keyword',
  `robotsIndex` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'index,follow' COMMENT 'Robots meta tag',
  PRIMARY KEY (`id`),
  KEY `brokerId` (`brokerId`),
  CONSTRAINT `Properties_ibfk_1` FOREIGN KEY (`brokerId`) REFERENCES `Users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
